  143	
  144	        $target = $this->target($report);
  145	        if ($target === null) {
  146	            return $this->reject('no_target', $playerId, $reportId);
  147	        }
  148	
  149	        // Target-class escalation (RV-011): the opening farms inactives only, a
  150	        // colonised account also raids active players, and an account past its
  151	        // mines can crash fleets. The rung is the phase machine's answer — it
  152	        // reads the planets the account owns and the research it has done —
  153	        // never a list of targets kept here.
  154	        if (!$this->targetEligible(app(GamePhaseMachine::class)->targetRung($player), $report)) {
  155	            return $this->reject('target_ineligible', $playerId, $reportId);
  156	        }
  157	
  158	        // A player does not raid someone the galaxy view marks as a newbie (under a fifth of their
  159	        // points) unless that account has gone idle: the host's own isNewbie answer, WIK-045.
  160	        if ($this->protectedNewbie($player, (int) $report->planet_user_id)) {
  161	            return $this->reject('newbie', $playerId, $reportId);
  162	        }
