21	/**
22	 * Module-owned adapter over the host's espionage fleet path.
23	 *
24	 * The decision and the target are the module's; the mission, its legality and
25	 * counter-espionage are the host's. One probe is sent and deducted atomically by
26	 * the host's own mission start.
27	 */
28	class QueueAiSpyAction implements QueueAiSpy
29	{
30	    public function __construct(
31	        private PlayerGameStateService $playerGameStateService,
32	        private PlanetServiceFactory $planetServiceFactory,
33	    ) {
34	    }
35	
36	    public function handle(int $playerId, int $planetId, int $targetGalaxy, int $targetSystem, int $targetPosition, int $targetType, int $probeCount = 1): AiActionResult
37	    {
38	        if (!Planet::query()->whereKey($planetId)->where('user_id', $playerId)->exists()) {
39	            return AiActionResult::rejected(AiQueueActionReason::PlanetNotOwned);
40	        }
41	
42	        try {
43	            $player = $this->playerGameStateService->advance($playerId, $planetId);
44	
45	            if ($player->isBanned()) {
46	                return AiActionResult::rejected(AiQueueActionReason::PlayerBanned);
47	            }
48	            if ($player->isInVacationMode()) {
49	                return AiActionResult::rejected(AiQueueActionReason::VacationMode);
50	            }
51	
52	            $planet = $this->planetServiceFactory->makeForPlayer($player, $planetId, false);
53	            // The ship the host's own espionage mission consumes; the name comes from the mission,
54	            // never from a module constant.
55	            $probe = ObjectService::getUnitObjectByMachineName(EspionageMission::getRequiredShipMachineNames()[0]);
56	            // Send what the origin actually holds: the plan may ask for a volley the planet cannot fill.
57	            $count = min(max(1, $probeCount), $planet->getShipUnits()->getAmountByMachineName($probe->machine_name));
58	            $units = new UnitCollection();
59	            $units->addUnit($probe, $count);
60	
61	            if (!app(FlightFuel::class)->affordable($player, $planet, $units, new Coordinate($targetGalaxy, $targetSystem, $targetPosition), 10)) {
62	                return AiActionResult::rejected(AiQueueActionReason::SourceShortAtDispatch);
63	            }
64	
65	            $fleetMissions = app()->makeWith(FleetMissionService::class, ['player' => $player]);
66	            $mission = $fleetMissions->createNewFromPlanet(
67	                $planet,
68	                new Coordinate($targetGalaxy, $targetSystem, $targetPosition),
69	                PlanetType::from($targetType),
70	                EspionageMission::getTypeId(),
71	                $units,
72	                new Resources(),
73	                10,
74	            );
75	
76	            return AiActionResult::queued($mission->id);
77	        } catch (Exception $exception) {
78	            return AiActionResult::rejected($exception->getMessage());
79	        }
80	    }
81	}

