 24	/**
 25	 * Module-owned adapter over the host's harvest (recycle) fleet path.
 26	 *
 27	 * The decision, the field and the harvest-hull count are the module's; the
 28	 * mission, its legality and the harvest itself are the host's. The hull is the
 29	 * one the host's own RecycleMission requires for the target slot.
 30	 */
 31	class QueueAiRecycleAction implements QueueAiRecycle
 32	{
 33	    /** The cheapest speed the host accepts (10%), a slow harvest run. */
 34	    private const RECYCLE_SPEED = 10.0;
 35	
 36	    public function __construct(
 37	        private PlayerGameStateService $playerGameStateService,
 38	        private PlanetServiceFactory $planetServiceFactory,
 39	    ) {
 40	    }
 41	
 42	    public function handle(int $playerId, int $planetId, int $targetGalaxy, int $targetSystem, int $targetPosition, int $targetType): AiActionResult
 43	    {
 44	        if (!Planet::query()->whereKey($planetId)->where('user_id', $playerId)->exists()) {
 45	            return AiActionResult::rejected(AiQueueActionReason::PlanetNotOwned);
 46	        }
 47	
 48	        try {
 49	            $player = $this->playerGameStateService->advance($playerId, $planetId);
 50	
 51	            if ($player->isBanned()) {
 52	                return AiActionResult::rejected(AiQueueActionReason::PlayerBanned);
 53	            }
 54	            if ($player->isInVacationMode()) {
 55	                return AiActionResult::rejected(AiQueueActionReason::VacationMode);
 56	            }
 57	
 58	            $origin = $this->planetServiceFactory->makeForPlayer($player, $planetId, false);
 59	            $fleet = $this->harvestFleet($player, $origin, $targetGalaxy, $targetSystem, $targetPosition);
 60	            if ($fleet === null) {
 61	                return $this->queueHarvestHull($player, $origin, $targetGalaxy, $targetSystem, $targetPosition);
 62	            }
 63	
 64	            $fleetMissions = app()->makeWith(FleetMissionService::class, ['player' => $player]);
 65	            $destination = new Coordinate($targetGalaxy, $targetSystem, $targetPosition);
 66	
 67	            // The host refuses a harvest the origin cannot fuel, so it is refused here by name.
 68	            $fuel = (float) $fleetMissions->calculateConsumption($origin, $fleet, $destination, 0, self::RECYCLE_SPEED);
 69	            if ($fuel > floor($origin->deuterium()->get()) || $fuel > $fleet->getTotalFuelCapacity($player)) {
 70	                return AiActionResult::rejected(AiQueueActionReason::SourceShortAtDispatch);
 71	            }
 72	
 73	            $mission = $fleetMissions->createNewFromPlanet(
 74	                $origin,
 75	                $destination,
 76	                PlanetType::from($targetType),
 77	                RecycleMission::getTypeId(),
 78	                $fleet,
 79	                new Resources(),
 80	                self::RECYCLE_SPEED,
 81	            );
 82	
 83	            return AiActionResult::queued($mission->id);
 84	        } catch (Exception $exception) {
 85	            return AiActionResult::rejected($exception->getMessage());
 86	        }
 87	    }
 88	
 89	    /**
 90	     * Enough harvest hulls to carry the field, capped by what the body holds.
 91	     *
 92	     * The hull is the one the host's RecycleMission requires for the slot and its
 93	     * capacity is the host's own figure, so a mod that changes either changes the
 94	     * count with no module edit. At least one hull flies for a field still worth
 95	     * a trip.
 96	     */
 97	    private function harvestFleet(PlayerService $player, PlanetService $origin, int $galaxy, int $system, int $position): ?UnitCollection
 98	    {
 99	        $ship = ObjectService::getShipObjectByMachineName(RecycleMission::getHarvesterMachineNameForPosition($position));
100	        $available = $origin->getShipUnits()->getAmountByMachineName($ship->machine_name);
101	        if ($available <= 0) {
102	            return null;
103	        }
104	
105	        $capacity = $ship->properties->capacity->calculate($player)->totalValue;
106	        $needed = (int) ceil($this->fieldMass($galaxy, $system, $position) / max(1, $capacity));
107	        $count = max(1, min($available, $needed));
108	
109	        $fleet = new UnitCollection();
110	        $fleet->addUnit($ship, $count);
111	
112	        return $fleet;
113	    }
114	
115	    /**
116	     * With no harvest hull on hand the intent builds the hull that collects the field
117	     * instead of failing, so a decided recycle eventually flies. The hull is the one the
118	     * host's RecycleMission requires for the slot, and the count is what the field needs:
119	     * a build is only ordered for a field that is still there.
120	     */
121	    private function queueHarvestHull(PlayerService $player, PlanetService $origin, int $galaxy, int $system, int $position): AiActionResult
122	    {
123	        $mass = $this->fieldMass($galaxy, $system, $position);
124	        if ($mass <= 0) {
125	            return AiActionResult::rejected(AiQueueActionReason::NoDisposableFleet);
126	        }
127	
128	        $ship = ObjectService::getShipObjectByMachineName(RecycleMission::getHarvesterMachineNameForPosition($position));
129	        $capacity = $ship->properties->capacity->calculate($player)->totalValue;
130	        $count = max(1, (int) ceil($mass / max(1, $capacity)));
131	
132	        app(UnitQueueService::class)->add($origin, $ship->id, $count);
133	
134	        return AiActionResult::queued($ship->id);
135	    }
136	
137	    /** The field's total mass at dispatch time, re-derived, never trusted from the decision. */
138	    private function fieldMass(int $galaxy, int $system, int $position): float
139	    {
140	        $field = DebrisField::query()
141	            ->where('galaxy', $galaxy)
142	            ->where('system', $system)
143	            ->where('planet', $position)
144	            ->first();
145	
146	        return $field === null ? 0.0 : (float) $field->metal + (float) $field->crystal + (float) $field->deuterium;
147	    }
148	}

