 3	namespace Modules\AI\Actions;
 4	
 5	use Exception;
 6	use Modules\AI\Contracts\QueueAiColony;
 7	use Modules\AI\Enums\AiQueueActionReason;
 8	use Modules\AI\Support\AiActionResult;
 9	use Modules\AI\Support\FlightFuel;
10	use OGame\Factories\PlanetServiceFactory;
11	use OGame\GameMissions\ColonisationMission;
12	use OGame\GameObjects\Models\Units\UnitCollection;
13	use OGame\Models\Enums\PlanetType;
14	use OGame\Models\Planet;
15	use OGame\Models\Planet\Coordinate;
16	use OGame\Models\Resources;
17	use OGame\Services\FleetMissionService;
18	use OGame\Services\ObjectService;
19	use OGame\Services\PlayerGameStateService;
20	
21	/**
22	 * Module-owned adapter over the host's colonisation fleet path.
23	 *
24	 * The decision is the module's; the mission, its legality and the slot check are
25	 * the host's. The colony ship is deducted atomically by the host's own mission
26	 * start, so this adapter only refuses what the host would refuse anyway and
27	 * reports whether a mission row actually appeared.
28	 */
29	class QueueAiColonyAction implements QueueAiColony
30	{
31	    public function __construct(
32	        private PlayerGameStateService $playerGameStateService,
33	        private PlanetServiceFactory $planetServiceFactory,
34	    ) {
35	    }
36	
37	    public function handle(int $playerId, int $planetId, int $galaxy, int $system, int $position): AiActionResult
38	    {
39	        if (!Planet::query()->whereKey($planetId)->where('user_id', $playerId)->exists()) {
40	            return AiActionResult::rejected(AiQueueActionReason::PlanetNotOwned);
41	        }
42	
43	        try {
44	            $player = $this->playerGameStateService->advance($playerId, $planetId);
45	
46	            if ($player->isBanned()) {
47	                return AiActionResult::rejected(AiQueueActionReason::PlayerBanned);
48	            }
49	            if ($player->isInVacationMode()) {
50	                return AiActionResult::rejected(AiQueueActionReason::VacationMode);
51	            }
52	
53	            $planet = $this->planetServiceFactory->makeForPlayer($player, $planetId, false);
54	            $units = new UnitCollection();
55	            // The ship the host's own colonisation mission consumes; the name comes from the
56	            // mission, never from a module constant.
57	            $colonyShip = ObjectService::getUnitObjectByMachineName(ColonisationMission::getRequiredShipMachineNames()[0]);
58	            $units->addUnit($colonyShip, 1);
59	
60	            if (!app(FlightFuel::class)->affordable($player, $planet, $units, new Coordinate($galaxy, $system, $position), 10)) {
61	                return AiActionResult::rejected(AiQueueActionReason::SourceShortAtDispatch);
62	            }
63	
64	            $fleetMissions = app()->makeWith(FleetMissionService::class, ['player' => $player]);
65	            $mission = $fleetMissions->createNewFromPlanet(
66	                $planet,
67	                new Coordinate($galaxy, $system, $position),
68	                PlanetType::Planet,
69	                ColonisationMission::getTypeId(),
70	                $units,
71	                new Resources(),
72	                10,
73	            );
74	
75	            return AiActionResult::queued($mission->id);
76	        } catch (Exception $exception) {
77	            return AiActionResult::rejected($exception->getMessage());
78	        }
79	    }
80	}

