 22	/**
 23	 * Module-owned adapter over the host's transport mission.
 24	 *
 25	 * The target legality, the cargo-capacity check and the atomic resource debit are the host's; the
 26	 * module adds the ship selection -- just enough of the cargo hulls the source already owns to carry
 27	 * the shipment, never the combat fleet a player would not risk on a ferry run.
 28	 */
 29	class QueueAiTransferAction implements QueueAiTransfer
 30	{
 31	    /** 100%: a ferry is wanted at the target, not parked in space. */
 32	    private const TRANSPORT_SPEED = 10.0;
 33	
 34	    public function __construct(
 35	        private PlayerGameStateService $playerGameStateService,
 36	        private PlanetServiceFactory $planetServiceFactory,
 37	        private AllyGiftGuard $giftGuard,
 38	    ) {
 39	    }
 40	
 41	    public function handle(int $playerId, int $sourcePlanetId, int $targetPlanetId, int $metal, int $crystal, int $deuterium): AiActionResult
 42	    {
 43	        if (!Planet::query()->whereKey($sourcePlanetId)->where('user_id', $playerId)->exists()) {
 44	            return AiActionResult::rejected(AiQueueActionReason::PlanetNotOwned);
 45	        }
 46	        // A target that is not the account's own is a gift, and only AllyGiftGuard decides whether
 47	        // one may leave: the guard re-reads the source stock below, once the shipment is final.
 48	        $gift = !Planet::query()->whereKey($targetPlanetId)->where('user_id', $playerId)->exists();
 49	        if ($gift && !Planet::query()->whereKey($targetPlanetId)->exists()) {
 50	            return AiActionResult::rejected(AiQueueActionReason::PlanetNotOwned);
 51	        }
 52	
 53	        try {
 54	            $player = $this->playerGameStateService->advance($playerId, $sourcePlanetId);
 55	
 56	            if ($player->isBanned()) {
 57	                return AiActionResult::rejected(AiQueueActionReason::PlayerBanned);
 58	            }
 59	            if ($player->isInVacationMode()) {
 60	                return AiActionResult::rejected(AiQueueActionReason::VacationMode);
 61	            }
 62	
 63	            $source = $this->planetServiceFactory->makeForPlayer($player, $sourcePlanetId, false);
 64	            $target = $gift
 65	                ? $this->planetServiceFactory->make($targetPlanetId, true)
 66	                : $this->planetServiceFactory->makeForPlayer($player, $targetPlanetId, false);
 67	            if ($target === null) {
 68	                return AiActionResult::rejected(AiQueueActionReason::PlanetNotOwned);
 69	            }
 70	
 71	            $shipment = $this->loadable($source, $metal, $crystal, $deuterium, $gift);
 72	            if ($shipment === null) {
 73	                return AiActionResult::rejected(AiQueueActionReason::SourceShortAtDispatch);
 74	            }
 75	
 76	            $shipment = $this->fittedToHold($player, $source, $shipment);
 77	            if ($gift) {
 78	                $refusal = $this->giftGuard->refusal(
 79	                    $playerId,
 80	                    $targetPlanetId,
 81	                    (int) $shipment->metal->get(),
 82	                    (int) $shipment->crystal->get(),
 83	                    (int) $shipment->deuterium->get(),
 84	                    $source->metal()->get(),
 85	                    $source->crystal()->get(),
 86	                    $source->deuterium()->get(),
 87	                );
 88	                if ($refusal !== null) {
 89	                    return AiActionResult::rejected($refusal);
 90	                }
 91	            }
 92	            $fleet = $this->transportFleet($player, $source, $shipment);
 93	            if ($fleet === null) {
 94	                return AiActionResult::rejected(AiQueueActionReason::NoTransportFleet);
 95	            }
 96	
 97	            $fleetMissions = app()->makeWith(FleetMissionService::class, ['player' => $player]);
 98	            $fuel = $fleetMissions->calculateConsumption($source, $fleet, $target->getPlanetCoordinates(), 0, self::TRANSPORT_SPEED);
 99	            if ($fuel > $fleet->getTotalFuelCapacity($player)) {
100	                // The minimal fleet's own tanks cannot carry a long flight's fuel: a player sends every
101	                // hold the planet owns before giving up the run (STUCK no_transport_fleet).
102	                $fleet = $this->everyHold($player, $source);
103	                $fuel = $fleet->units === [] ? PHP_INT_MAX : $fleetMissions->calculateConsumption($source, $fleet, $target->getPlanetCoordinates(), 0, self::TRANSPORT_SPEED);
104	            }
105	            if ($fuel > $fleet->getTotalFuelCapacity($player)) {
106	                return AiActionResult::rejected(AiQueueActionReason::NoTransportFleet);
107	            }
108	            if ($fuel > floor($source->deuterium()->get())) {
109	                return AiActionResult::rejected(AiQueueActionReason::SourceShortAtDispatch);
110	            }
111	
112	            $shipment = $this->leavingFuelBehind($source, $shipment, $fleet, $target, $fleetMissions);
113	            $shipment = $this->fittedBesideFuel($player, $fleet, $shipment, (int) ceil($fuel));
114	
115	            $mission = $fleetMissions->createNewFromPlanet(
116	                $source,
117	                $target->getPlanetCoordinates(),
118	                $target->getPlanetType(),
119	                TransportMission::getTypeId(),
120	                $fleet,
121	                $shipment,
122	                self::TRANSPORT_SPEED,
123	            );
124	
125	            return AiActionResult::queued($mission->id);
126	        } catch (Exception $exception) {
127	            return AiActionResult::rejected($exception->getMessage());
128	        }
129	    }
