131	    /**
132	     * The flight's fuel rides in the same hold as the cargo, so a shipment that fills the hold
133	     * leaves no room for it and the host refuses with insufficient storage capacity. A player
134	     * loads what is left of the hold after the fuel.
135	     */
136	    private function fittedBesideFuel(PlayerService $player, UnitCollection $fleet, Resources $shipment, int $fuel): Resources
137	    {
138	        $room = max(0, $fleet->getTotalCargoCapacity($player) - $fuel);
139	        $total = $shipment->sum();
140	        if ($total <= $room) {
141	            return $shipment;
142	        }
143	
144	        $share = $room / $total;
145	
146	        return new Resources(
147	            floor($shipment->metal->get() * $share),
148	            floor($shipment->crystal->get() * $share),
149	            floor($shipment->deuterium->get() * $share),
150	        );
151	    }
152	
153	    /**
154	     * The shipment is quoted when the session decides, but a work item can run minutes later and at
155	     * this game speed the source has spent part of the surplus by then: the host refuses a flight
156	     * whose cargo the planet no longer holds, which is what most refused transfers were. A player
157	     * loads what is still on the pad, so each resource is clamped to the source's own stock, and a
158	     * remnant below the ordinary minimum is abandoned instead of flying a fleet for it.
159	     */
160	    private function loadable(PlanetService $source, int $metal, int $crystal, int $deuterium, bool $gift = false): ?Resources
161	    {
162	        $held = [
163	            (int) floor($source->metal()->get()),
164	            (int) floor($source->crystal()->get()),
165	            (int) floor($source->deuterium()->get()),
166	        ];
167	
168	        // Nothing was spent between the decision and this dispatch, so the quote stands.
169	        if ($metal <= $held[0] && $crystal <= $held[1] && $deuterium <= $held[2]) {
170	            return new Resources($metal, $crystal, $deuterium);
171	        }
172	
173	        $shipment = new Resources(min($metal, $held[0]), min($crystal, $held[1]), min($deuterium, $held[2]));
174	
175	        // A gift is capped at a tenth of the stock, so the own-ferry floor does not apply to it.
176	        if (!$gift && $shipment->metal->get() + $shipment->crystal->get() < QueueableTransferPlanner::MINIMUM_SHIPMENT) {
177	            return null;
178	        }
179	
180	        return $shipment;
181	    }
182	
183	    /**
184	     * The host demands the cargo *and* the flight's own fuel on the origin planet, so a shipment that
185	     * takes the last deuterium is refused for resources even though the cargo itself fits. The fuel
186	     * is the host's own figure for this fleet and route; a player leaves it behind and flies with
187	     * the rest.
188	     */
189	    private function leavingFuelBehind(PlanetService $source, Resources $shipment, UnitCollection $fleet, PlanetService $target, FleetMissionService $fleetMissions): Resources
190	    {
191	        $fuel = $fleetMissions->calculateConsumption($source, $fleet, $target->getPlanetCoordinates(), 0, self::TRANSPORT_SPEED);
192	        $spare = (int) floor($source->deuterium()->get()) - (int) ceil($fuel);
193	
194	        return new Resources(
195	            $shipment->metal->get(),
196	            $shipment->crystal->get(),
197	            min($shipment->deuterium->get(), max(0, $spare)),
198	        );
199	    }
200	
201	    /**
202	     * Just enough of the cargo hulls the source already owns to carry the shipment, or null when the
203	     * source's fleet cannot carry it. Ships without cargo capacity are never taken, so a ferry run
204	     * never moves the combat fleet.
205	     */
206	    /**
207	     * A player ships what the hold takes: a store of millions beside a few hundred cargo ships sends
208	     * a full fleet's load, it is not refused for being bigger than the fleet.
209	     */
210	    private function fittedToHold(PlayerService $player, PlanetService $source, Resources $shipment): Resources
211	    {
212	        $capacity = $source->getShipUnits()->getTotalCargoCapacity($player);
213	        $total = $shipment->sum();
214	        if ($capacity <= 0 || $total <= $capacity) {
215	            return $shipment;
216	        }
217	
218	        $share = $capacity / $total;
219	
220	        return new Resources(
221	            floor($shipment->metal->get() * $share),
222	            floor($shipment->crystal->get() * $share),
223	            floor($shipment->deuterium->get() * $share),
224	        );
225	    }
226	
227	    /**
228	     * The deuterium the ferry's own flight burns from this source, or null when it has no fleet that
229	     * can carry the shipment. The planner asks it before publishing, so a source that cannot pay the
230	     * fuel is not offered the way a player does not plan a run with empty tanks.
231	     */
232	    public function flightFuel(PlayerService $player, PlanetService $source, PlanetService $target, Resources $shipment): float|null
233	    {
234	        $fleet = $this->transportFleet($player, $source, $this->fittedToHold($player, $source, $shipment));
235	        if ($fleet === null) {
236	            return null;
237	        }
238	        $fleetMissions = app()->makeWith(FleetMissionService::class, ['player' => $player]);
239	        $fuel = (float) $fleetMissions->calculateConsumption($source, $fleet, $target->getPlanetCoordinates(), 0, self::TRANSPORT_SPEED);
240	
241	        // The tanks too: the dispatch refuses a flight the fleet cannot carry the fuel for, so a ferry
242	        // that fails that test is not planned in the first place.
243	        return $fuel > $fleet->getTotalFuelCapacity($player) ? null : $fuel;
244	    }
245	
246	    private function transportFleet(PlayerService $player, PlanetService $source, Resources $shipment): ?UnitCollection
247	    {
248	        $fleet = new UnitCollection();
249	        $remaining = $shipment->sum();
250	        if ($remaining <= 0) {
251	            return null;
252	        }
253	
254	        foreach ($this->holdsByCapacity($player, $source) as $entry) {
255	            $capacity = $entry->unitObject->properties->capacity->calculate($player)->totalValue;
256	
257	            $amount = min((int) ceil($remaining / $capacity), $entry->amount);
258	
259	            $fleet->addUnit($entry->unitObject, $amount);
260	            $remaining -= $amount * $capacity;
261	            if ($remaining <= 0) {
262	                return $fleet;
263	            }
264	        }
265	
266	        return null;
267	    }
268	
269	    /**
270	     * Biggest holds first: a player ferries with cargo ships, and a fleet padded with fighters
271	     * burns more deuterium than its own tanks carry, which the host refuses as storage capacity.
272	     *
273	     * @return array<UnitEntry>
274	     */
275	    private function holdsByCapacity(PlayerService $player, PlanetService $source): array
276	    {
277	        $entries = [];
278	        foreach ($source->getShipUnits()->units as $entry) {
279	            $capacity = $entry->unitObject->properties->capacity->calculate($player)->totalValue;
280	            if ($capacity > 0) {
281	                $entries[] = [$capacity, $entry];
282	            }
283	        }
284	        usort($entries, static fn (array $a, array $b): int => $b[0] <=> $a[0]);
285	
286	        return array_map(static fn (array $pair) => $pair[1], $entries);
287	    }
288	
289	    /** Every hull with a hold that the source owns, whole stacks: the widest fleet a ferry can fly with. */
290	    private function everyHold(PlayerService $player, PlanetService $source): UnitCollection
291	    {
292	        $fleet = new UnitCollection();
293	        foreach ($this->holdsByCapacity($player, $source) as $entry) {
294	            $fleet->addUnit($entry->unitObject, $entry->amount);
295	        }
296	
297	        return $fleet;
298	    }
299	}

