            $system = $receipt->result['decision']['target_system'] ?? null;
            $position = $receipt->result['decision']['target_position'] ?? null;
            if ($galaxy !== null && $system !== null && $position !== null) {
                $coordinates[$galaxy . ':' . $system . ':' . $position] = true;
