 15	/**
 16	 * Replays a saved scenario through the real decision engine without writing anything.
 17	 *
 18	 * A replay is how one decision is questioned without touching an account: the scenario names the
 19	 * persona, the legal observation and the frozen time, and the engine then has to produce the same
 20	 * answer on every run. That is the property worth having — a decision nobody can reproduce is a
 21	 * decision nobody can argue with.
 22	 *
 23	 * The persona is an unsaved profile, so replaying a scenario cannot create, change or enable an
 24	 * account, and every field is read through an explicit accessor: a malformed scenario reports
 25	 * which field is wrong instead of deciding from a half-read file.
 26	 */
 27	class ReplayAiScenarioAction
 28	{
 29	    /**
 30	     * A reserved id that no real account can hold, so the synthetic persona is never read from
 31	     * the profiles table even on a universe that has profiles.
 32	     */
 33	    private const SYNTHETIC_PLAYER_ID = 0;
 34	
 35	    private const SCENARIO_DIRECTORY = 'resources/scenarios';
 36	
 37	    /**
 38	     * The scenarios that ship with the module. The admin page can only replay one of these, so
 39	     * a page request cannot be turned into a read of an arbitrary file on the host.
 40	     *
 41	     * @return list<string>
 42	     */
 43	    public function names(): array
 44	    {
 45	        $names = [];
 46	
 47	        foreach (glob(module_path('AI', self::SCENARIO_DIRECTORY . '/*.json')) ?: [] as $path) {
 48	            $names[] = basename($path, '.json');
 49	        }
 50	
 51	        sort($names);
 52	
 53	        return $names;
 54	    }
