 91	    /**
 92	     * Fail the replay when the engine did not do what the scenario says it must.
 93	     *
 94	     * Without `expect` a scenario only reports what happened. With it, the scenario becomes an
 95	     * acceptance check for one rule under the exact conditions it describes -- a player in this
 96	     * situation must take this action -- which is the difference between proving the rule works and
 97	     * proving a class exists.
 98	     *
 99	     * @param array<string, mixed> $scenario
100	     */
101	    private function assertExpected(array $scenario, AiScenarioReplay $replay): void
102	    {
103	        $expect = $scenario['expect'] ?? null;
104	        if (!is_array($expect)) {
105	            return;
106	        }
107	
108	        $action = $expect['action'] ?? null;
109	        if (is_string($action) && strcasecmp($action, $replay->selectedAction) !== 0) {
110	            throw new RuntimeException(sprintf(
111	                'Scenario expected action %s but the engine chose %s (%s). Alternatives: %s',
112	                $action,
113	                $replay->selectedAction,
114	                $replay->selectedReason,
115	                json_encode($replay->alternatives)
116	            ));
117	        }
118	
119	        $reason = $expect['reason_contains'] ?? null;
120	        if (is_string($reason) && !str_contains(strtolower($replay->selectedReason), strtolower($reason))) {
121	            throw new RuntimeException(sprintf(
122	                'Scenario expected the selected reason to contain "%s" but it was "%s".',
123	                $reason,
124	                $replay->selectedReason
125	            ));
126	        }
127	    }
