130	     * @return array<string, mixed>
131	     */
132	    private function load(string $path): array
133	    {
134	        if (!is_file($path)) {
135	            throw new RuntimeException('Scenario file not found: ' . $path);
136	        }
137	
138	        $decoded = json_decode((string) file_get_contents($path), true);
139	
140	        if (!is_array($decoded)) {
141	            throw new RuntimeException('Scenario is not valid JSON: ' . $path);
142	        }
143	
144	        // Presence is checked before anything is read, so a scenario that is missing a whole
145	        // section is reported as missing rather than as whatever field is read first.
146	        foreach (['name', 'persona', 'input', 'decision_key'] as $key) {
147	            if (!array_key_exists($key, $decoded)) {
148	                throw new RuntimeException('Scenario is missing "' . $key . '": ' . $path);
149	            }
150	        }
151	
152	        return $decoded;
153	    }
