 10	/**
 11	 * What the host or the dispatch gate refused this account a moment ago.
 12	 *
 13	 * A refused dispatch is not a mission, so nothing the planners read recorded it and the same target or
 14	 * the same origin was offered again on the next login (measured 4 Oct 2026: one account tried one
 15	 * target 21 times in six hours). A player who was told "that planet is online" leaves it alone for a
 16	 * while; this is that memory, read from the receipts the gate already writes.
 17	 */
 18	class RecentRefusals
 19	{
 20	    private const WINDOW_MINUTES = 45;
 21	
 22	    /**
 23	     * The two refusals the gate raises about the *target*: a planet that is online or staging says
 24	     * nothing about the body the fleet would leave from, so an origin is never blamed for them.
 25	     */
 26	    private const TARGET_SIDE_REASONS = [
 27	        AiQueueActionReason::TargetActiveAtDispatch->value,
 28	        AiQueueActionReason::TargetStagingAtDispatch->value,
 29	    ];
 30	
 31	    public function target(int $playerId, int $galaxy, int $system, int $position): bool
 32	    {
 33	        return isset($this->refusedTargets($playerId)["{$galaxy}:{$system}:{$position}"]);
 34	    }
 35	
 36	    /**
 37	     * Whether the window holds a refusal that blamed this origin — for one of $reasons when the caller
 38	     * names them, otherwise for whatever the gate said.
 39	     */
 40	    public function origin(int $playerId, int $planetId, string ...$reasons): bool
 41	    {
 42	        return $this->recent($playerId)
 43	            ->reject($this->targetSide(...))
 44	            ->contains(fn (AiActionReceipt $receipt): bool => ($receipt->result['planet_id'] ?? null) === $planetId
 45	                && ($reasons === [] || in_array($receipt->result['reason'] ?? null, $reasons, true)));
 46	    }
 47	
 48	    /**
 49	     * The coordinates the window's refusals named, keyed "g:s:p": a planner holding a candidate list
 50	     * skips them in one read instead of one query per candidate.
 51	     *
 52	     * @return array<string, true>
 53	     */
 54	    public function refusedTargets(int $playerId): array
 55	    {
 56	        $coordinates = [];
 57	
 58	        foreach ($this->recent($playerId) as $receipt) {
 59	            $galaxy = $receipt->result['decision']['target_galaxy'] ?? null;
 60	            $system = $receipt->result['decision']['target_system'] ?? null;
 61	            $position = $receipt->result['decision']['target_position'] ?? null;
 62	
 63	            if ($galaxy !== null && $system !== null && $position !== null) {
 64	                $coordinates["{$galaxy}:{$system}:{$position}"] = true;
 65	            }
 66	        }
 67	
 68	        return $coordinates;
 69	    }
 70	
 71	    /**
 72	     * The own bodies the window's refusals blamed, keyed by planet id.
 73	     *
 74	     * An origin the gate refused is an origin a player leaves alone for a while, and the reason is not
 75	     * read: the host raises some of them as free text a planner cannot name ("Not enough units on the
 76	     * planet to send the fleet. Units required: colony_ship"), and each one says the dispatch from this
 77	     * body did not happen. Only the target-side reasons are excluded.
 78	     *
 79	     * @return array<int, true>
 80	     */
 81	    public function refusedOrigins(int $playerId): array
 82	    {
 83	        $origins = [];
 84	
 85	        foreach ($this->recent($playerId)->reject($this->targetSide(...)) as $receipt) {
 86	            $planetId = $receipt->result['planet_id'] ?? null;
 87	
 88	            if ($planetId !== null) {
 89	                $origins[(int) $planetId] = true;
 90	            }
 91	        }
 92	
 93	        return $origins;
 94	    }
 95	
 96	    /** A refusal about the target is no fault of the body the fleet would leave from. */
 97	    private function targetSide(AiActionReceipt $receipt): bool
 98	    {
 99	        return in_array($receipt->result['reason'] ?? null, self::TARGET_SIDE_REASONS, true);
100	    }
101	
102	    /** @return \Illuminate\Support\Collection<int, AiActionReceipt> */
103	    private function recent(int $playerId)
104	    {
105	        return AiActionReceipt::query()
106	            ->where('player_id', $playerId)
107	            ->where('action_type', AiActionType::DispatchFleet->value)
108	            ->where('state', AiReceiptState::Rejected->value)
109	            ->where('created_at', '>', now()->subMinutes(self::WINDOW_MINUTES))
110	            ->get();
111	    }
112	}

